import { WebSocketFn } from "wasp/server/webSocket";

let ioInstance: any = null;

export const webSocketFn: WebSocketFn = (io, context) => {
  ioInstance = io;

  io.on("connection", (socket) => {
    console.log("A user connected: ", socket.data.user?.username);

    socket.on("joinDocument", (documentId: number) => {
      socket.join(`document-${documentId}`);
      console.log(`Socket ${socket.id} joined document-${documentId}`);
    });

    socket.on("leaveDocument", (documentId: number) => {
      socket.leave(`document-${documentId}`);
      console.log(`Socket ${socket.id} left document-${documentId}`);
    });

    socket.on("editDocument", async ({ documentId, content }: { documentId: number; content: string }) => {
      // Broadcast the change to other users in the room
      socket.to(`document-${documentId}`).emit("documentUpdated", { content });

      // Save the content to the database
      try {
        await context.entities.Document.update({
          where: { id: Number(documentId) },
          data: { content },
        });
      } catch (err) {
        console.error("Error saving document content: ", err);
      }
    });

    socket.on("disconnect", () => {
      console.log("A user disconnected: ", socket.data.user?.username);
    });
  });
};

export function broadcastDocumentUpdate(documentId: number, content: string) {
  if (ioInstance) {
    ioInstance.to(`document-${documentId}`).emit("documentUpdated", { content });
  }
}

import { type GetDocuments, type GetDocument, type GetVersions, type GetPermissions } from "wasp/server/operations";
import { HttpError } from "wasp/server";

export const getDocuments: GetDocuments<void, any[]> = async (_args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }

  return context.entities.Document.findMany({
    where: {
      OR: [
        { ownerId: context.user.id },
        {
          permissions: {
            some: {
              userId: context.user.id,
            },
          },
        },
      ],
    },
    orderBy: { createdAt: "desc" },
    include: {
      owner: true,
      permissions: {
        include: {
          user: true,
        },
      },
    },
  });
};

export const getDocument: GetDocument<{ id: number }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }

  const document = await context.entities.Document.findUnique({
    where: { id: Number(args.id) },
    include: {
      owner: true,
      permissions: {
        include: {
          user: true,
        },
      },
    },
  });

  if (!document) {
    throw new HttpError(404, "Document not found");
  }

  let role: string | null = null;
  if (document.ownerId === context.user.id) {
    role = "OWNER";
  } else {
    const permission = document.permissions.find(p => p.userId === context.user.id);
    if (permission) {
      role = permission.role;
    }
  }

  if (!role) {
    throw new HttpError(403, "Access Denied");
  }

  return { document, role };
};

export const getVersions: GetVersions<{ documentId: number }, any[]> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }

  const document = await context.entities.Document.findUnique({
    where: { id: Number(args.documentId) },
    include: {
      permissions: true,
    },
  });

  if (!document) {
    throw new HttpError(404, "Document not found");
  }

  const hasAccess = document.ownerId === context.user.id || document.permissions.some(p => p.userId === context.user.id);
  if (!hasAccess) {
    throw new HttpError(403, "Access Denied");
  }

  return context.entities.Version.findMany({
    where: { documentId: Number(args.documentId) },
    orderBy: { createdAt: "asc" },
    include: {
      author: true,
    },
  });
};

export const getPermissions: GetPermissions<{ documentId: number }, any[]> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }

  const document = await context.entities.Document.findUnique({
    where: { id: Number(args.documentId) },
  });

  if (!document) {
    throw new HttpError(404, "Document not found");
  }

  if (document.ownerId !== context.user.id) {
    throw new HttpError(403, "Only the owner can view permissions");
  }

  return context.entities.Permission.findMany({
    where: { documentId: Number(args.documentId) },
    include: {
      user: true,
    },
  });
};

import { type CreateDocument, type ShareDocument, type RevokePermission, type SaveVersion, type RestoreVersion } from "wasp/server/operations";
import { HttpError } from "wasp/server";
import { broadcastDocumentUpdate } from "./webSocket";

export const createDocument: CreateDocument<{ title: string }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }

  if (!args.title || typeof args.title !== 'string') {
    throw new HttpError(400, "Title is required");
  }

  return context.entities.Document.create({
    data: {
      title: args.title,
      ownerId: context.user.id,
      content: "",
    },
  });
};

export const shareDocument: ShareDocument<{ documentId: number; username: string; role: string }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }

  const document = await context.entities.Document.findUnique({
    where: { id: Number(args.documentId) },
  });

  if (!document) {
    throw new HttpError(404, "Document not found");
  }

  if (document.ownerId !== context.user.id) {
    throw new HttpError(403, "Only the owner can share the document");
  }

  const targetUser = await context.entities.User.findUnique({
    where: { username: args.username },
  });

  if (!targetUser) {
    throw new HttpError(404, `User ${args.username} not found`);
  }

  if (targetUser.id === context.user.id) {
    throw new HttpError(400, "You cannot share a document with yourself");
  }

  if (args.role !== "VIEW" && args.role !== "EDIT") {
    throw new HttpError(400, "Invalid role");
  }

  return context.entities.Permission.upsert({
    where: {
      documentId_userId: {
        documentId: Number(args.documentId),
        userId: targetUser.id,
      },
    },
    update: {
      role: args.role,
    },
    create: {
      documentId: Number(args.documentId),
      userId: targetUser.id,
      role: args.role,
    },
  });
};

export const revokePermission: RevokePermission<{ documentId: number; userId: number }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }

  const document = await context.entities.Document.findUnique({
    where: { id: Number(args.documentId) },
  });

  if (!document) {
    throw new HttpError(404, "Document not found");
  }

  if (document.ownerId !== context.user.id) {
    throw new HttpError(403, "Only the owner can revoke permissions");
  }

  return context.entities.Permission.delete({
    where: {
      documentId_userId: {
        documentId: Number(args.documentId),
        userId: Number(args.userId),
      },
    },
  });
};

export const saveVersion: SaveVersion<{ documentId: number; content: string }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }

  const document = await context.entities.Document.findUnique({
    where: { id: Number(args.documentId) },
    include: {
      permissions: true,
    },
  });

  if (!document) {
    throw new HttpError(404, "Document not found");
  }

  const isOwner = document.ownerId === context.user.id;
  const permission = document.permissions.find(p => p.userId === context.user.id);
  const hasEditAccess = isOwner || (permission && permission.role === "EDIT");

  if (!hasEditAccess) {
    throw new HttpError(403, "Only owners or editors can save versions");
  }

  const version = await context.entities.Version.create({
    data: {
      documentId: Number(args.documentId),
      content: args.content,
      authorId: context.user.id,
    },
  });

  await context.entities.Document.update({
    where: { id: Number(args.documentId) },
    data: { content: args.content },
  });

  return version;
};

export const restoreVersion: RestoreVersion<{ documentId: number; versionId: number }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Not authenticated");
  }

  const document = await context.entities.Document.findUnique({
    where: { id: Number(args.documentId) },
    include: {
      permissions: true,
    },
  });

  if (!document) {
    throw new HttpError(404, "Document not found");
  }

  const isOwner = document.ownerId === context.user.id;
  const permission = document.permissions.find(p => p.userId === context.user.id);
  const hasEditAccess = isOwner || (permission && permission.role === "EDIT");

  if (!hasEditAccess) {
    throw new HttpError(403, "Only owners or editors can restore versions");
  }

  const version = await context.entities.Version.findUnique({
    where: { id: Number(args.versionId) },
  });

  if (!version || version.documentId !== Number(args.documentId)) {
    throw new HttpError(404, "Version not found");
  }

  await context.entities.Document.update({
    where: { id: Number(args.documentId) },
    data: { content: version.content },
  });

  broadcastDocumentUpdate(Number(args.documentId), version.content);

  return version;
};

import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { DocumentPage } from "./src/DocumentPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };

import { getDocuments, getDocument, getVersions, getPermissions } from "./src/queries" with { type: "ref" };
import { createDocument, shareDocument, revokePermission, saveVersion, restoreVersion } from "./src/actions" with { type: "ref" };
import { userSignupFields } from "./src/auth" with { type: "ref" };
import { webSocketFn } from "./src/webSocket" with { type: "ref" };

export default app({
  name: "app",
  title: "app",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {
        userSignupFields,
      },
    },
    onAuthFailedRedirectTo: "/login",
  },
  webSocket: {
    fn: webSocketFn,
    autoConnect: true,
  },
  spec: [
    route("SignupRoute", "/signup", page(SignupPage)),
    route("LoginRoute", "/login", page(LoginPage)),
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("DocumentRoute", "/document/:id", page(DocumentPage, { authRequired: true })),

    query(getDocuments, { entities: ["Document", "Permission"] }),
    query(getDocument, { entities: ["Document", "Permission"] }),
    query(getVersions, { entities: ["Document", "Version"] }),
    query(getPermissions, { entities: ["Document", "Permission"] }),

    action(createDocument, { entities: ["Document"] }),
    action(shareDocument, { entities: ["Document", "Permission", "User"] }),
    action(revokePermission, { entities: ["Document", "Permission"] }),
    action(saveVersion, { entities: ["Document", "Version"] }),
    action(restoreVersion, { entities: ["Document", "Version"] }),
  ],
});

