import { useState, FormEvent } from "react";
import { Link } from "react-router";
import { useQuery, getDocuments, createDocument } from "wasp/client/operations";
import { useAuth, logout } from "wasp/client/auth";
import "./Main.css";

export function MainPage() {
  const { data: user } = useAuth();
  const { data: documents, isLoading, error } = useQuery(getDocuments);
  const [title, setTitle] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [createError, setCreateError] = useState("");

  const handleCreateDocument = async (e: FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;

    setIsSubmitting(true);
    setCreateError("");
    try {
      await createDocument({ title: title.trim() });
      setTitle("");
    } catch (err: any) {
      setCreateError(err.message || "Failed to create document");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div style={{ maxWidth: "800px", margin: "40px auto", padding: "0 20px", fontFamily: "sans-serif" }}>
      <header style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "40px", borderBottom: "1px solid #eee", paddingBottom: "20px" }}>
        <div>
          <h1 style={{ margin: 0 }}>Collaborative Doc Editor</h1>
          {user && <p style={{ margin: "5px 0 0 0", color: "#666" }}>Logged in as: <strong>{user.username}</strong></p>}
        </div>
        <button 
          onClick={logout}
          style={{ padding: "8px 16px", backgroundColor: "#f44336", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
        >
          Logout
        </button>
      </header>

      <section style={{ marginBottom: "40px", padding: "20px", backgroundColor: "#f9f9f9", borderRadius: "8px" }}>
        <h2 style={{ margin: "0 0 20px 0" }}>Create a New Document</h2>
        <form onSubmit={handleCreateDocument} style={{ display: "flex", gap: "10px" }}>
          <input
            id="document-title-input"
            type="text"
            placeholder="Enter document title..."
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            disabled={isSubmitting}
            style={{ flex: 1, padding: "10px", fontSize: "16px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
          <button
            id="create-document-btn"
            type="submit"
            disabled={isSubmitting}
            style={{ padding: "10px 20px", fontSize: "16px", backgroundColor: "#0070f3", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
          >
            {isSubmitting ? "Creating..." : "Create Document"}
          </button>
        </form>
        {createError && <p style={{ color: "red", marginTop: "10px", marginBottom: 0 }}>{createError}</p>}
      </section>

      <section>
        <h2>Your Documents</h2>
        {isLoading && <p>Loading documents...</p>}
        {error && <p style={{ color: "red" }}>Error loading documents: {error.message}</p>}

        {!isLoading && !error && (!documents || documents.length === 0) && (
          <p style={{ color: "#666", fontStyle: "italic" }}>No documents found. Create one above to get started!</p>
        )}

        {documents && documents.length > 0 && (
          <ul style={{ listStyle: "none", padding: 0, margin: 0, display: "flex", flexDirection: "column", gap: "15px" }}>
            {documents.map((doc) => {
              const isOwner = user && doc.ownerId === user.id;
              const userPerm = user && doc.permissions.find((p: any) => p.userId === user.id);
              const roleLabel = isOwner ? "Owner" : `Shared: ${userPerm?.role}`;

              return (
                <li key={doc.id} style={{ padding: "20px", border: "1px solid #ddd", borderRadius: "8px", display: "flex", justifyContent: "space-between", alignItems: "center", backgroundColor: "white" }}>
                  <div>
                    <h3 style={{ margin: "0 0 5px 0" }}>
                      <Link to={`/document/${doc.id}`} style={{ color: "#0070f3", textDecoration: "none", fontWeight: "bold" }}>
                        {doc.title}
                      </Link>
                    </h3>
                    <p style={{ margin: 0, fontSize: "14px", color: "#666" }}>
                      Owner: {doc.owner.username} | Role: <span style={{ fontWeight: "bold", color: isOwner ? "#2e7d32" : "#ed6c02" }}>{roleLabel}</span>
                    </p>
                  </div>
                  <Link 
                    to={`/document/${doc.id}`}
                    style={{ padding: "8px 16px", backgroundColor: "#0070f3", color: "white", textDecoration: "none", borderRadius: "4px", fontSize: "14px" }}
                  >
                    Open Editor
                  </Link>
                </li>
              );
            })}
          </ul>
        )}
      </section>
    </div>
  );
}

import { useState, useEffect, FormEvent } from "react";
import { useParams, Link } from "react-router";
import { useQuery, getDocument, getVersions, getPermissions, shareDocument, revokePermission, saveVersion, restoreVersion } from "wasp/client/operations";
import { useSocket, useSocketListener } from "wasp/client/webSocket";
import { useAuth } from "wasp/client/auth";

export function DocumentPage() {
  const { id } = useParams<{ id: string }>();
  const { data: user } = useAuth();
  const { socket, isConnected } = useSocket();

  const { data: docData, error: docError, isLoading: docLoading } = useQuery(getDocument, { id: Number(id) });
  const { data: versions, refetch: refetchVersions } = useQuery(getVersions, { documentId: Number(id) });

  const isOwner = docData?.role === "OWNER";
  const isEditor = docData?.role === "EDIT" || isOwner;

  const { data: permissions, refetch: refetchPermissions } = useQuery(
    getPermissions,
    { documentId: Number(id) },
    { enabled: isOwner }
  );

  const [content, setContent] = useState("");
  const [hasInitializedContent, setHasInitializedContent] = useState(false);

  // Sharing form state
  const [shareUsername, setShareUsername] = useState("");
  const [shareRole, setShareRole] = useState("VIEW");
  const [shareError, setShareError] = useState("");
  const [shareSuccess, setShareSuccess] = useState("");

  const [saveError, setSaveError] = useState("");

  // Initialize content on load
  useEffect(() => {
    if (docData && !hasInitializedContent) {
      setContent(docData.document.content);
      setHasInitializedContent(true);
    }
  }, [docData, hasInitializedContent]);

  // WebSocket Room Join/Leave
  useEffect(() => {
    if (socket && isConnected && id) {
      socket.emit("joinDocument", Number(id));
    }
    return () => {
      if (socket && isConnected && id) {
        socket.emit("leaveDocument", Number(id));
      }
    };
  }, [socket, isConnected, id]);

  // Real-time edits listener
  useSocketListener("documentUpdated", ({ content: updatedContent }: { content: string }) => {
    setContent(updatedContent);
  });

  const handleTextareaChange = (newContent: string) => {
    setContent(newContent);
    if (socket && isConnected) {
      socket.emit("editDocument", { documentId: Number(id), content: newContent });
    }
  };

  const handleSaveVersion = async () => {
    setSaveError("");
    try {
      await saveVersion({
        documentId: Number(id),
        content,
      });
      refetchVersions();
    } catch (err: any) {
      setSaveError(err.message || "Failed to save version");
    }
  };

  const handleRestoreVersion = async (versionId: number) => {
    try {
      await restoreVersion({
        documentId: Number(id),
        versionId,
      });
      refetchVersions();
    } catch (err: any) {
      alert(err.message || "Failed to restore version");
    }
  };

  const handleShare = async (e: FormEvent) => {
    e.preventDefault();
    if (!shareUsername.trim()) return;
    setShareError("");
    setShareSuccess("");
    try {
      await shareDocument({
        documentId: Number(id),
        username: shareUsername.trim(),
        role: shareRole,
      });
      setShareUsername("");
      setShareSuccess(`Successfully shared with ${shareUsername}`);
      refetchPermissions();
    } catch (err: any) {
      setShareError(err.message || "Failed to share document");
    }
  };

  const handleRevoke = async (userId: number) => {
    try {
      await revokePermission({
        documentId: Number(id),
        userId,
      });
      refetchPermissions();
    } catch (err: any) {
      alert(err.message || "Failed to revoke permission");
    }
  };

  if (docLoading) {
    return <div style={{ padding: "40px", textAlign: "center" }}>Loading document...</div>;
  }

  if (docError) {
    const isAccessDenied = docError.status === 403 || docError.message?.includes("Access Denied");
    return (
      <div style={{ padding: "40px", textAlign: "center", fontFamily: "sans-serif" }}>
        <h1>{isAccessDenied ? "Access Denied" : "Error"}</h1>
        <p>{isAccessDenied ? "You do not have permission to view this document." : (docError.message || "Failed to load document")}</p>
        <Link to="/" style={{ color: "#0070f3", textDecoration: "none", fontWeight: "bold" }}>Go back to Homepage</Link>
      </div>
    );
  }

  if (!docData) {
    return (
      <div style={{ padding: "40px", textAlign: "center", fontFamily: "sans-serif" }}>
        <h1>Document Not Found</h1>
